/**
 * Audio playback and speech synthesis manager for UKG assistant.
 * Supports playing WAV audio generated by Gemini 3.8 Flash Lite TTS
 * and fallback to Web Speech API with Hindi female voice.
 */

class AudioPlayerManager {
  private currentAudio: HTMLAudioElement | null = null;
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private mediaSourceNode: MediaElementAudioSourceNode | null = null;

  public initContext(): AudioContext | null {
    if (typeof window === 'undefined') return null;
    if (!this.audioContext) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioCtx) {
        this.audioContext = new AudioCtx();
        this.analyser = this.audioContext.createAnalyser();
        this.analyser.fftSize = 128;
      }
    }
    if (this.audioContext && this.audioContext.state === 'suspended') {
      this.audioContext.resume().catch(() => {});
    }
    return this.audioContext;
  }

  public getAnalyser(): AnalyserNode | null {
    this.initContext();
    return this.analyser;
  }

  /**
   * Play base64 WAV audio from Gemini TTS
   */
  public async playWavBase64(base64Data: string, onEnded?: () => void): Promise<HTMLAudioElement> {
    this.stop();
    this.initContext();

    const audioUrl = `data:audio/wav;base64,${base64Data}`;
    const audio = new Audio(audioUrl);
    this.currentAudio = audio;

    // Connect to Web Audio Analyser if supported
    if (this.audioContext && this.analyser) {
      try {
        if (!this.mediaSourceNode) {
          this.mediaSourceNode = this.audioContext.createMediaElementSource(audio);
          this.mediaSourceNode.connect(this.analyser);
          this.analyser.connect(this.audioContext.destination);
        }
      } catch (err) {
        // Some browsers disallow re-connecting same element; standard destination fallback
      }
    }

    return new Promise((resolve, reject) => {
      audio.onended = () => {
        this.currentAudio = null;
        if (onEnded) onEnded();
      };
      audio.onerror = (e) => {
        this.currentAudio = null;
        reject(e);
      };
      audio
        .play()
        .then(() => resolve(audio))
        .catch((err) => {
          this.currentAudio = null;
          reject(err);
        });
    });
  }

  /**
   * Fallback speech synthesis using Hindi female browser voice
   */
  public speakWithBrowserHindi(
    text: string,
    speechRate = 1.0,
    onEnded?: () => void
  ): Promise<void> {
    this.stop();
    return new Promise((resolve) => {
      if (typeof window === 'undefined' || !('speechSynthesis' in window)) {
        if (onEnded) onEnded();
        resolve();
        return;
      }

      window.speechSynthesis.cancel();
      const cleanText = text.replace(/[*#_`~>]/g, '').trim();
      const utterance = new SpeechSynthesisUtterance(cleanText);

      // Try finding Hindi female voice
      const voices = window.speechSynthesis.getVoices();
      const hindiVoice = voices.find(
        (v) =>
          (v.lang.startsWith('hi') || v.lang.includes('IN')) &&
          (v.name.toLowerCase().includes('female') ||
            v.name.toLowerCase().includes('kavya') ||
            v.name.toLowerCase().includes('lekha') ||
            v.name.toLowerCase().includes('google हिन्दी') ||
            v.name.toLowerCase().includes('zira'))
      ) || voices.find((v) => v.lang.startsWith('hi'));

      if (hindiVoice) {
        utterance.voice = hindiVoice;
      }
      utterance.lang = 'hi-IN';
      utterance.rate = speechRate;
      utterance.pitch = 1.15; // Slightly higher pitch for warm female voice

      utterance.onend = () => {
        if (onEnded) onEnded();
        resolve();
      };
      utterance.onerror = () => {
        if (onEnded) onEnded();
        resolve();
      };

      window.speechSynthesis.speak(utterance);
    });
  }

  public stop(): void {
    if (this.currentAudio) {
      this.currentAudio.pause();
      this.currentAudio.currentTime = 0;
      this.currentAudio = null;
    }
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      window.speechSynthesis.cancel();
    }
  }

  public isPlaying(): boolean {
    return (
      (this.currentAudio !== null && !this.currentAudio.paused) ||
      (typeof window !== 'undefined' &&
        'speechSynthesis' in window &&
        window.speechSynthesis.speaking)
    );
  }
}

export const audioPlayer = new AudioPlayerManager();
